def solve(payload):
    import re
    def version(value):
        if not re.fullmatch(r"(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)", value):
            raise ValueError()
        return tuple(map(int, value.split(".")))
    try:
        dependencies = [(d, version(d["version"])) for d in payload["dependencies"]]
        advisories = []
        for a in payload["advisories"]:
            lower = version(a["introduced"])
            upper = None if a["fixed"] is None else version(a["fixed"])
            if upper is not None and upper <= lower:
                raise ValueError()
            advisories.append((a, lower, upper))
    except ValueError:
        return {"error": "invalid_version"}
    findings = []
    for dep, current in dependencies:
        ids = sorted({a["id"] for a, low, high in advisories if a["name"] == dep["name"] and low <= current and (high is None or current < high)})
        if ids:
            findings.append({"name": dep["name"], "version": dep["version"], "advisories": ids})
    return {"findings": findings}

